using System.Text.Json;

namespace Castor.AI.Worker.Tests.Football;

/// <summary>
/// Frames and Python results generated by scripts/generate_football_fixtures.py with the real
/// Castor-AI detector (ultralytics + checkpoint_5.pt).
/// </summary>
internal static class Fixtures
{
    private static readonly string Directory = Path.Combine(AppContext.BaseDirectory, "Football", "Fixtures");
    private static readonly Lazy<JsonElement> Expected = new(() =>
        JsonDocument.Parse(File.ReadAllText(Path.Combine(Directory, "expected.json"))).RootElement);

    public static int Width => Expected.Value.GetProperty("width").GetInt32();

    public static int Height => Expected.Value.GetProperty("height").GetInt32();

    public static int Stride => Width * 4;

    /// <summary>The frame as the worker gets it from shared memory: BGRA, alpha 255.</summary>
    public static byte[] Bgra(string name)
    {
        var bgr = File.ReadAllBytes(Path.Combine(Directory, $"{name}.bgr"));
        var bgra = new byte[bgr.Length / 3 * 4];
        for (int i = 0, j = 0; i < bgr.Length; i += 3, j += 4)
        {
            bgra[j] = bgr[i];
            bgra[j + 1] = bgr[i + 1];
            bgra[j + 2] = bgr[i + 2];
            bgra[j + 3] = 255;
        }

        return bgra;
    }

    /// <summary>Best confidence per class of the boxes Python kept. Variants: python, python_fp32, rgb_fp32.</summary>
    public static Dictionary<int, float> BestPerClass(string name, string variant)
    {
        var best = new Dictionary<int, float>();
        foreach (var box in Expected.Value.GetProperty("frames").GetProperty(name).GetProperty(variant).EnumerateArray())
        {
            var cls = box.GetProperty("class").GetInt32();
            var confidence = box.GetProperty("confidence").GetSingle();
            best[cls] = Math.Max(best.GetValueOrDefault(cls), confidence);
        }

        return best;
    }
}
